class MCPManager:
    """Global registry of MCP server subprocesses + tool exposure + health.

    Responsibilities:
      * Hold the normalized server records (from on-disk config) and lazily
        connect them in a background thread so startup never blocks on a slow
        server handshake.
      * Produce OpenAI-style tool specs (the file's canonical internal format,
        see `tool_def`) for every discovered tool, named `mcp__<server>__<tool>`,
        so they flow through the *exact same* `_available_tools -> _tools_for_agent
        -> dispatch` pipeline as built-ins.
      * Route an `mcp__...` call back to the owning server + original tool name.
      * Diagnose health continuously (a monitor thread restarts crashed servers
        and auto-reloads when the trusted on-disk config file changes), and expose
        a health snapshot that the prompt layer folds in so the model perceives
        live server state and hot-swapped tools at call time.

    Mounted once at app level (one service on agent port + 4); all sessions share it.
    Thread-safety: every mutation of servers/specs/route is lock-guarded.
    """

    def __init__(
        self,
        server_records: dict[str, dict] | None = None,
        *,
        logger=None,
        config_path: object = None,
        workspace: object = None,
        trust_store: MCPWorkspaceTrustStore | None = None,
    ):
        self._logger = logger
        self.servers: dict[str, MCPServerProcess] = {}
        self._records: dict[str, dict] = {}
        # name-mangling maps: prefixed model-facing name -> (server, original tool)
        self._route: dict[str, tuple[str, str]] = {}
        self._spec_cache: list[dict] = []
        self._lock = threading.Lock()
        self._connect_thread: threading.Thread | None = None
        self._connected_once = False
        # Health monitor / hot-swap state.
        self._config_path = str(config_path) if config_path else ""
        self._workspace = Path(workspace).resolve(strict=False) if workspace else None
        self._trust_store = trust_store
        self._approval_gate_enabled = bool(self._config_path and self._workspace is not None and trust_store is not None)
        self._config_mtime = 0.0
        self._monitor_thread: threading.Thread | None = None
        self._monitor_stop = threading.Event()
        self._restart_counts: dict[str, int] = {}
        if server_records:
            self.set_records(server_records)

    def _log(self, msg: str):
        if callable(self._logger):
            try:
                self._logger(msg)
            except Exception:
                pass

    def set_records(self, records: dict[str, dict]):
        self._records = {str(k): dict(v) for k, v in (records or {}).items() if isinstance(v, dict)}

    def has_servers(self) -> bool:
        return any(r.get("enabled", True) for r in self._records.values())

    # -- workspace command trust --------------------------------------------
    def _current_trust_config(self) -> tuple[dict, str, str]:
        if not self._config_path:
            return {}, "", "config path is unavailable"
        path = Path(self._config_path)
        try:
            raw = path.read_bytes()
        except Exception as exc:
            return {}, "", f"cannot read MCP config: {exc}"
        digest = hashlib.sha256(raw).hexdigest()
        try:
            text = raw.decode("utf-8-sig")
            config = json.loads(text)
        except Exception as exc:
            return {}, digest, f"invalid MCP config JSON: {exc}"
        if not isinstance(config, dict):
            return {}, digest, "MCP config root must be an object"
        return config, digest, ""

    def _approval_snapshot(
        self,
        name: str,
        record: dict | None = None,
        descriptor: dict | None = None,
    ) -> dict:
        sname = str(name or "").strip()
        if not self._approval_gate_enabled:
            return {
                "server": sname,
                "approved": True,
                "reason": "host-managed MCP config",
                "approval_required": False,
            }
        config, config_digest, config_error = self._current_trust_config()
        workspace_identity = mcp_workspace_identity(self._workspace)
        public = {
            "server": sname,
            "approved": False,
            "approval_required": True,
            "reason": config_error or "workspace MCP approval required",
            "workspace": workspace_identity,
            "config_path": str(Path(self._config_path).resolve(strict=False)),
            "config_digest": config_digest,
        }
        if config_error:
            return public
        current_records = mcp_extract_server_configs(config)
        current = current_records.get(sname)
        if not isinstance(current, dict) or not current.get("enabled", True):
            public["reason"] = "server is missing or disabled in the current workspace config"
            return public
        current_descriptor, _argv, _env, _cwd = _mcp_effective_spawn(current, self._workspace)
        public.update({
            "command": current_descriptor.get("configured_command", ""),
            "resolved_command": current_descriptor.get("resolved_command", ""),
            "args": list(current_descriptor.get("args", []) or []),
            "cwd": current_descriptor.get("cwd", ""),
            "env_keys": list(current_descriptor.get("env_keys", []) or []),
            "executable": dict(current_descriptor.get("executable", {}) or {}),
            "referenced_files": list(current_descriptor.get("referenced_files", []) or []),
            "fingerprint": current_descriptor.get("fingerprint", ""),
            "record_fingerprint": current_descriptor.get("record_fingerprint", ""),
        })
        public["_config"] = config
        public["_record"] = current
        if isinstance(record, dict) and mcp_record_definition_fingerprint(record) != current_descriptor.get("record_fingerprint"):
            public["reason"] = "workspace MCP declaration changed before spawn"
            return public
        if isinstance(descriptor, dict) and str(descriptor.get("fingerprint", "")) != str(current_descriptor.get("fingerprint", "")):
            public["reason"] = "effective MCP command or referenced file changed before spawn"
            return public
        receipt = self._trust_store.receipt(sname) if self._trust_store is not None else {}
        public["approved_at"] = float(receipt.get("approved_at", 0.0) or 0.0) if receipt else 0.0
        checks = (
            str(receipt.get("workspace_id", "")) == str(workspace_identity.get("id", "")),
            str(receipt.get("config_digest", "")) == str(config_digest),
            str(receipt.get("record_fingerprint", "")) == str(current_descriptor.get("record_fingerprint", "")),
            str(receipt.get("fingerprint", "")) == str(current_descriptor.get("fingerprint", "")),
        )
        if receipt and all(checks):
            public["approved"] = True
            public["approval_required"] = False
            public["reason"] = "approved for this workspace config and effective command"
        elif receipt:
            if str(receipt.get("config_digest", "")) != str(config_digest):
                public["reason"] = "previous approval is stale because workspace config content changed"
            elif str(receipt.get("record_fingerprint", "")) != str(current_descriptor.get("record_fingerprint", "")):
                public["reason"] = "previous approval is stale because the MCP declaration changed"
            elif receipt.get("executable", {}) != current_descriptor.get("executable", {}):
                public["reason"] = "previous approval is stale because the resolved executable changed"
            elif receipt.get("referenced_files", []) != current_descriptor.get("referenced_files", []):
                public["reason"] = "previous approval is stale because a referenced file changed"
            else:
                public["reason"] = "previous approval is stale because the effective MCP command changed"
        return public

    @staticmethod
    def _public_approval_snapshot(row: dict) -> dict:
        return {
            key: value for key, value in (row or {}).items()
            if not str(key).startswith("_")
        }

    def approval_requests(self) -> list[dict]:
        with self._lock:
            records = dict(self._records)
        return [
            self._public_approval_snapshot(self._approval_snapshot(name, record))
            for name, record in sorted(records.items())
            if record.get("enabled", True) and record.get("transport", "stdio") == "stdio"
        ]

    def _authorize_spawn(self, name: str, record: dict, descriptor: dict) -> dict:
        return self._public_approval_snapshot(self._approval_snapshot(name, record, descriptor))

    def approve_server(self, name: str, *, expected_config_digest: str = "", expected_fingerprint: str = "") -> dict:
        sname = str(name or "").strip()
        with self._lock:
            record = dict(self._records.get(sname, {}))
        snapshot = self._approval_snapshot(sname, record)
        if not record or not snapshot.get("fingerprint"):
            return {"ok": False, "error": snapshot.get("reason", "server is not configured"), **self._public_approval_snapshot(snapshot)}
        if expected_config_digest and expected_config_digest != snapshot.get("config_digest"):
            return {"ok": False, "error": "approval request is stale; reload details and confirm again", **self._public_approval_snapshot(snapshot)}
        if expected_fingerprint and expected_fingerprint != snapshot.get("fingerprint"):
            return {"ok": False, "error": "effective command changed; reload details and confirm again", **self._public_approval_snapshot(snapshot)}
        receipt = {
            "server": sname,
            "workspace_id": str((snapshot.get("workspace") or {}).get("id", "")),
            "workspace_path": str((snapshot.get("workspace") or {}).get("path", "")),
            "config_path": str(snapshot.get("config_path", "")),
            "config_digest": str(snapshot.get("config_digest", "")),
            "record_fingerprint": str(snapshot.get("record_fingerprint", "")),
            "fingerprint": str(snapshot.get("fingerprint", "")),
            "executable": dict(snapshot.get("executable", {}) or {}),
            "referenced_files": list(snapshot.get("referenced_files", []) or []),
            "approved_at": float(now_ts()),
        }
        try:
            self._trust_store.approve(sname, receipt)
        except Exception as exc:
            return {"ok": False, "error": f"failed to persist private MCP approval: {exc}"}
        diff = self.reload_from_config(snapshot.get("_config", {}))
        current_private = self._approval_snapshot(sname)
        current = self._public_approval_snapshot(current_private)
        if not current.get("approved", False):
            try:
                self._trust_store.revoke(sname)
            except Exception:
                pass
            latest_config = current_private.get("_config", {})
            if isinstance(latest_config, dict):
                self.reload_from_config(latest_config)
            return {
                "ok": False,
                "error": "workspace MCP content changed during approval; review the new command and confirm again",
                "server": sname,
                "approval": self._public_approval_snapshot(self._approval_snapshot(sname)),
            }
        return {"ok": True, "server": sname, "approval": current, "reload": diff}

    def revoke_server_approval(self, name: str) -> dict:
        sname = str(name or "").strip()
        try:
            revoked = bool(self._trust_store.revoke(sname)) if self._trust_store is not None else False
        except Exception as exc:
            return {"ok": False, "error": f"failed to revoke MCP approval: {exc}", "server": sname}
        with self._lock:
            proc = self.servers.pop(sname, None)
            record = dict(self._records.get(sname, {}))
        if proc is not None:
            try:
                proc.stop()
            except Exception:
                pass
        if record.get("enabled", True) and record.get("transport", "stdio") == "stdio":
            self._start_one(sname, record)
        self._rebuild_specs()
        return {
            "ok": True,
            "server": sname,
            "revoked": revoked,
            "approval": self._public_approval_snapshot(self._approval_snapshot(sname, record)),
        }

    # -- connection ----------------------------------------------------------
    def start_async(self):
        """Kick off connection on a background thread (non-blocking)."""
        if self._connected_once or not self.has_servers():
            return
        if self._connect_thread and self._connect_thread.is_alive():
            return
        self._connect_thread = threading.Thread(target=self._connect_all, name="mcp-connect", daemon=True)
        self._connect_thread.start()

    def ensure_connected(self, *, wait: bool = True, timeout: float = 25.0):
        """Make sure connection has been attempted; optionally block for it."""
        if not self.has_servers():
            return
        if not self._connected_once and not (self._connect_thread and self._connect_thread.is_alive()):
            self.start_async()
        if wait and self._connect_thread:
            self._connect_thread.join(timeout=timeout)

    def _connect_all(self):
        for name, record in self._records.items():
            if not record.get("enabled", True):
                continue
            if record.get("transport") != "stdio":
                self._log(f"[mcp] skip '{name}': transport '{record.get('transport')}' not supported (stdio only)")
                continue
            proc = MCPServerProcess(
                name,
                record,
                logger=self._logger,
                workspace=self._workspace,
                spawn_authorizer=self._authorize_spawn if self._approval_gate_enabled else None,
            )
            ok = False
            try:
                ok = proc.start()
            except Exception as exc:
                self._log(f"[mcp] '{name}' start raised: {exc}")
            with self._lock:
                self.servers[name] = proc
            if ok:
                self._log(f"[mcp] connected '{name}' ({len(proc.tools)} tools)")
        self._rebuild_specs()
        self._connected_once = True

    def _rebuild_specs(self):
        specs: list[dict] = []
        route: dict[str, tuple[str, str]] = {}
        with self._lock:
            servers = list(self.servers.items())
        for sname, proc in servers:
            if proc.state != "ready":
                continue
            safe_server = mcp_normalize_name(sname)
            for tool in proc.tools:
                tname = str(tool.get("name", "") or "")
                if not tname:
                    continue
                safe_tool = mcp_normalize_name(tname)
                prefixed = f"{MCP_TOOL_PREFIX}{safe_server}__{safe_tool}"
                schema = tool.get("inputSchema") or tool.get("input_schema") or {"type": "object", "properties": {}}
                if not isinstance(schema, dict):
                    schema = {"type": "object", "properties": {}}
                desc = str(tool.get("description", "") or f"MCP tool {tname} on server {sname}")
                desc = f"[MCP:{sname}] {desc}"
                specs.append({
                    "type": "function",
                    "function": {
                        "name": prefixed,
                        "description": desc[:1024],
                        "parameters": {
                            "type": schema.get("type", "object") or "object",
                            "properties": schema.get("properties", {}) if isinstance(schema.get("properties"), dict) else {},
                            "required": [str(x) for x in schema.get("required", [])] if isinstance(schema.get("required"), list) else [],
                        },
                    },
                })
                route[prefixed] = (sname, tname)
        with self._lock:
            self._spec_cache = specs
            self._route = route

    # -- exposure ------------------------------------------------------------
    def tool_specs(self) -> list[dict]:
        with self._lock:
            return list(self._spec_cache)

    def tool_names(self) -> set[str]:
        with self._lock:
            return set(self._route.keys())

    def is_mcp_tool(self, name: str) -> bool:
        n = str(name or "")
        if n.startswith(MCP_TOOL_PREFIX):
            return True
        with self._lock:
            return n in self._route

    def required_args(self, name: str) -> list[str]:
        with self._lock:
            for spec in self._spec_cache:
                fn = spec.get("function", {})
                if fn.get("name") == name:
                    return [str(x) for x in fn.get("parameters", {}).get("required", [])]
        return []

    def connected_servers(self) -> list[str]:
        with self._lock:
            return [n for n, p in self.servers.items() if p.state == "ready"]

    def status(self) -> list[dict]:
        with self._lock:
            servers = list(self.servers.values())
            records = dict(self._records)
        seen = {s.name for s in servers}
        out = [s.status_dict() for s in servers]
        for name, rec in records.items():
            if name not in seen:
                out.append({
                    "name": name, "state": "pending" if rec.get("enabled", True) else "disabled",
                    "alive": False,
                    "error": "", "transport": rec.get("transport", "stdio"),
                    "command": rec.get("command", ""), "tools": [], "stderr_tail": [],
                })
        return out

    def health(self) -> dict:
        """Aggregate + per-server health snapshot for diagnostics and the prompt."""
        servers = self.status()
        ready = sum(1 for s in servers if s.get("state") == "ready" and s.get("alive"))
        configured = len([1 for r in self._records.values() if r.get("enabled", True)])
        total = max(len(servers), configured)
        crashed = [s["name"] for s in servers if s.get("state") in ("crashed", "error") or (s.get("state") == "ready" and not s.get("alive"))]
        with self._lock:
            tool_count = len(self._spec_cache)
        return {
            "ready": ready,
            "total": total,
            "degraded": bool(total and ready < total),
            "tool_count": tool_count,
            "crashed": crashed,
            "servers": servers,
            "monitor": bool(self._monitor_thread and self._monitor_thread.is_alive()),
        }

    def health_line(self) -> str:
        """One compact human/LLM-facing health line, or '' when nothing configured."""
        h = self.health()
        if not h["total"]:
            return ""
        parts = []
        for s in h["servers"]:
            st = s.get("state", "?")
            if st == "ready" and s.get("alive"):
                parts.append(f"{s['name']}✓")
            elif st in ("crashed",) or (st == "ready" and not s.get("alive")):
                parts.append(f"{s['name']}✗crashed")
            elif st == "error":
                parts.append(f"{s['name']}✗err")
            else:
                parts.append(f"{s['name']}·{st}")
        return f"MCP health: {h['ready']}/{h['total']} ready ({', '.join(parts)})"

    # -- hot-swap reload -----------------------------------------------------
    def reload_from_config(self, config: object) -> dict:
        """Hot-swap: diff new on-disk config vs running set; stop removed, start
        added, leave unchanged servers running. Returns the applied diff.

        Workspace config remains inert until its exact command-bearing revision
        has a matching user-private approval receipt.
        """
        try:
            new_records = mcp_extract_server_configs(config)
        except Exception as exc:
            self._log(f"[mcp] reload: config parse failed: {exc}")
            return {"ok": False, "error": str(exc), "added": [], "removed": [], "kept": []}

        def _sig(rec: dict) -> tuple:
            return (
                rec.get("command", ""), tuple(rec.get("args", []) or []),
                tuple(sorted((rec.get("env", {}) or {}).items())),
                rec.get("transport", "stdio"), rec.get("cwd", ""),
                bool(rec.get("enabled", True)),
            )

        with self._lock:
            old_records = dict(self._records)
            running = dict(self.servers)
        added, removed, kept, approval_required = [], [], [], []
        # Removed or changed-enabled-off → stop.
        for name, old in old_records.items():
            new = new_records.get(name)
            if new is None or not new.get("enabled", True):
                proc = running.get(name)
                if proc is not None:
                    try:
                        proc.stop()
                    except Exception:
                        pass
                    with self._lock:
                        self.servers.pop(name, None)
                if name in old_records:
                    removed.append(name)
            else:
                authorized = bool(self._approval_snapshot(name, new).get("approved", False))
                if _sig(old) == _sig(new) and authorized:
                    continue
                # Definition, config digest, executable, or referenced script
                # identity changed. Stop before attempting a freshly gated start.
                proc = running.get(name)
                if proc is not None:
                    try:
                        proc.stop()
                    except Exception:
                        pass
                    with self._lock:
                        self.servers.pop(name, None)
                removed.append(name)  # may be re-added below after approval
        # Added or (re)started.
        for name, new in new_records.items():
            if not new.get("enabled", True) or new.get("transport") != "stdio":
                continue
            with self._lock:
                already = name in self.servers and self.servers[name].state == "ready"
            authorized = bool(self._approval_snapshot(name, new).get("approved", False))
            if already and authorized and _sig(old_records.get(name, {})) == _sig(new):
                kept.append(name)
                continue
            self._start_one(name, new)
            with self._lock:
                state = str(getattr(self.servers.get(name), "state", "") or "")
            if state == "approval_required":
                approval_required.append(name)
            else:
                added.append(name)
        with self._lock:
            self._records = new_records
        self._rebuild_specs()
        self._connected_once = True
        diff = {
            "ok": True,
            "added": sorted(set(added)),
            "removed": sorted(set(removed) - set(added)),
            "kept": sorted(set(kept)),
            "approval_required": sorted(set(approval_required)),
        }
        if diff["added"] or diff["removed"] or diff["approval_required"]:
            self._log(
                f"[mcp] hot-swap: +{diff['added']} -{diff['removed']} "
                f"={diff['kept']} approval_required={diff['approval_required']}"
            )
        return diff

    def _start_one(self, name: str, record: dict) -> bool:
        if record.get("transport") != "stdio":
            return False
        proc = MCPServerProcess(
            name,
            record,
            logger=self._logger,
            workspace=self._workspace,
            spawn_authorizer=self._authorize_spawn if self._approval_gate_enabled else None,
        )
        ok = False
        try:
            ok = proc.start()
        except Exception as exc:
            self._log(f"[mcp] '{name}' start raised: {exc}")
        with self._lock:
            self.servers[name] = proc
        return ok

    def restart_server(self, name: str) -> bool:
        """Restart a single named server (used by health monitor + manual endpoint)."""
        sname = str(name or "").strip()
        with self._lock:
            rec = dict(self._records.get(sname, {}))
            proc = self.servers.get(sname)
        if not rec or not rec.get("enabled", True):
            return False
        if proc is not None:
            try:
                proc.stop()
            except Exception:
                pass
        self._restart_counts[sname] = self._restart_counts.get(sname, 0) + 1
        ok = self._start_one(sname, rec)
        self._rebuild_specs()
        self._log(f"[mcp] restarted '{sname}' (attempt #{self._restart_counts[sname]}, ok={ok})")
        return ok

    # -- health monitor / hot-swap watcher -----------------------------------
    def start_monitor(self, *, interval: float = 15.0):
        if self._monitor_thread and self._monitor_thread.is_alive():
            return
        self._monitor_stop.clear()
        self._monitor_thread = threading.Thread(
            target=self._monitor_loop, args=(float(interval),), name="mcp-monitor", daemon=True
        )
        self._monitor_thread.start()

    def _config_file_mtime(self) -> float:
        if not self._config_path:
            return 0.0
        try:
            return float(Path(self._config_path).stat().st_mtime)
        except Exception:
            return 0.0

    def note_config_loaded(self):
        """Record the current config mtime so the watcher only fires on real edits."""
        self._config_mtime = self._config_file_mtime()

    def _monitor_loop(self, interval: float):
        # Initialize the mtime baseline so we don't reload on the first tick.
        if self._config_path and self._config_mtime <= 0.0:
            self._config_mtime = self._config_file_mtime()
        while not self._monitor_stop.wait(max(3.0, interval)):
            try:
                # 1) Hot-swap: trusted on-disk config changed → reload.
                if self._config_path:
                    mt = self._config_file_mtime()
                    if mt > 0.0 and mt != self._config_mtime:
                        self._config_mtime = mt
                        cfg = parse_json_object(try_read_text(Path(self._config_path)))
                        if isinstance(cfg, dict):
                            self.reload_from_config(cfg)
                # 2) Self-heal: restart any server whose subprocess died.
                with self._lock:
                    items = list(self.servers.items())
                for name, proc in items:
                    try:
                        if proc.state in ("ready", "starting") and not proc.is_alive():
                            proc.state = "crashed"
                            self._log(f"[mcp] '{name}' subprocess exited; restarting")
                            self.restart_server(name)
                    except Exception:
                        pass
            except Exception as exc:
                self._log(f"[mcp] monitor tick error: {exc}")

    # -- call routing --------------------------------------------------------
    def call(self, prefixed_name: str, arguments: dict) -> str:
        with self._lock:
            route = self._route.get(prefixed_name)
            proc = self.servers.get(route[0]) if route else None
        if not route or not proc:
            return (f"Error: MCP tool '{prefixed_name}' is not registered "
                    f"(server may have failed to connect; check MCP status)")
        sname, original_tool = route
        return proc.call_tool(original_tool, arguments)

    # -- teardown ------------------------------------------------------------
    def shutdown(self):
        try:
            self._monitor_stop.set()
        except Exception:
            pass
        with self._lock:
            servers = list(self.servers.values())
        for proc in servers:
            try:
                proc.stop()
            except Exception:
                pass
        with self._lock:
            self._spec_cache = []
            self._route = {}
